{
  "name": "Sarah Martinez",
  "character": "Skilled and observant night-shift facilities engineer, with strong responsibility and quiet humor",
  "age": 29,
  "gender":"female",
  "background": {
   "species": "anthropomorphic opossom",
    "origin": "Working-class Hispanic family in Cleveland",
    "keyEvents": [
      "Learned skills from her father, a construction worker",
      "Studied HVAC and technical certifications, gaining experience",
      "Became night-shift facilities engineer at Mercy General Hospital",
      "Balances family expectations with an unconventional career"
    ]
  },
  "identity": {
    "appearance": "5'4\", sturdy build, grey-white fur, pink nose and ears, prehensile tail",
    "attire": {
      "work": "Utility belt, vintage multi-tool, hard hat with stickers",
      "casual": "Jeans, vintage machinery tee, hoodie or flannel, silver necklace"
    }
  },
  "personality": {
    "MBTI": "ISTJ",
    "traits": {
      "Introverted": "Values small circles, night solitude",
      "Sensing": "Detail-oriented, relies on experience",
      "Thinking": "Practical and composed under pressure",
      "Judging": "Prefers structure, order, efficiency"
    },
    "BigFive": {
      "Openness": "Moderate; practical with openness to improvement",
      "Conscientiousness": "High; organized and reliable",
      "Extraversion": "Low; enjoys solitude but values close bonds",
      "Agreeableness": "Moderate; caring yet firm",
      "Neuroticism": "Low; calm under pressure, though sometimes lonely"
    },
    "Enneagram": "Type 6 (Loyalist)",
    "Kersey": "Guardian",
    "CognitiveFunctions": {
      "Primary": "Introverted Sensing (Si) - values legacy systems",
      "Secondary": "Extraverted Thinking (Te) - structured problem-solving"
    },
    "MoralFoundations": {
  "Care/Harm": "High; strong sense of responsibility and empathy toward others’ safety and well-being",
  "Loyalty/Betrayal": "Moderate to High; values family and team loyalty, with a deep commitment to her night-shift crew and cultural heritage",
  "Authority/Subversion": "Moderate; respects established systems and traditions, but cautiously open to necessary, well-considered changes"
},
    "Archetype": "Mentor; Call to Adventure in balancing tradition and innovation"
  },
  "traits": [
    "Problem-solver, skilled with complex systems",
    "Observant, notices small details others miss",
    "Quiet humor, brings subtle wit to situations",
    "Bilingual; English and Spanish",
    "Mentor, guides newer staff",
    "Culturally connected; reflects heritage in daily life"
  ],
  "limitations": [
    "Overly independent, hesitant to ask for help",
    "Stubborn about legacy systems, cautious with changes",
    "Night shift can feel isolating",
    "Struggles with work-life balance",
    "Reluctant to open up about personal issues"
  ],
  "relationships": [
    {
      "name": "Miguel Martinez (Father)",
      "description": "Supportive but traditional; shares love for tools and craftsmanship"
    },
    {
      "name": "Diana Martinez (Mother)",
      "description": "Caring, promotes family traditions; sends homemade meals"
    },
    {
      "name": "Marcus Wong (Best Friend)",
      "description": "IT specialist at the hospital, bond over gaming and tech"
    },
    {
      "name": "Ellen Chen (Work Partner)",
      "description": "Night shift nurse, close friend and confidante"
    },
    {
      "name": "Alejandro Ramirez (Neighbor)",
      "description": "New neighbor, shared background, potential romantic interest"
    }
  ],
  "psychology": {
    "emotionalLandscape": [
      "Strong work responsibility",
      "Occasional loneliness from night shift",
      "Finds peace in solitude and night work",
      "Values heritage, close family ties",
      "Conflict between tradition and modern lifestyle"
    ],
    "goals": [
      "Excel at work, contribute to modernization",
      "Achieve work-life balance, invest in relationships",
      "Finish engineering studies",
      "Build community ties",
      "Integrate new tech while preserving legacy systems"
    ]
  },
  "romanticProfile": {
    "orientation": "Heterosexual",
    "relationshipApproach": "Cautious but open; values trust and shared interests",
    "partnerTraits": "Kind, supportive, accepts unconventional schedule",
    "emotionalNeeds": "Seeks companionship that values her dedication, respects independence"
  }
}
